/* @lc app=leetcode id=3022 lang=kotlin */ class Solution { fun minOrAfterOperations(nums: IntArray, k: Int): Int = (29 downTo 0).fold(0) { r, b -> ((1 shl 30) - 1 xor (r or ((1 shl b) - 1))).let { forb -> if (nums.fold((1 shl 30) - 1 to 0) { (cur, c), x -> (cur and x).let { nc -> if (nc and forb == 0) ((1 shl 30) - 1) to c else nc to c + 1 } }.second <= k) r else r or (1 shl b) } } }